export type GrammarLevel = "A1" | "A2" | "B1" | "B2" | "C1";

export interface GrammarPoint {
  id: string;
  level: GrammarLevel;
  category: string;
  title: string;
  titleVi: string;
  pattern: string;
  explanation: string;
  examples: string[];
  exampleTranslations: string[];
  commonMistake: {
    incorrect: string;
    correct: string;
    explanation: string;
  };
}

type Example = [english: string, vietnamese: string];
type Mistake = [incorrect: string, correct: string, explanation: string];

function point(
  id: string,
  level: GrammarLevel,
  category: string,
  title: string,
  titleVi: string,
  pattern: string,
  explanation: string,
  examples: Example[],
  commonMistake: Mistake
): GrammarPoint {
  return {
    id,
    level,
    category,
    title,
    titleVi,
    pattern,
    explanation,
    examples: examples.map(([english]) => english),
    exampleTranslations: examples.map(([, vietnamese]) => vietnamese),
    commonMistake: {
      incorrect: commonMistake[0],
      correct: commonMistake[1],
      explanation: commonMistake[2],
    },
  };
}

